      out.write("    document.getElementById('modalHeadcount').textContent = count + ' nhân sự';\r\n");
      out.write("    document.getElementById('modalReason').textContent = reason;\r\n");
      out.write("    document.getElementById('modalSalary').textContent = sal;\r\n");
      out.write("    document.getElementById('modalDeadline').textContent = deadline || 'Chưa đặt';\r\n");
      out.write("\r\n");
      out.write("    var jd = document.getElementById('jd-' + id) ? document.getElementById('jd-' + id).textContent.trim() : '';\r\n");
      out.write("    var req = document.getElementById('req-' + id) ? document.getElementById('req-' + id).textContent.trim() : '';\r\n");
      out.write("    var exp = document.getElementById('exp-' + id) ? document.getElementById('exp-' + id).textContent.trim() : '';\r\n");
      out.write("\r\n");
      out.write("    document.getElementById('modalJobDescription').textContent = jd || '(Chưa có mô tả công việc)';\r\n");
      out.write("    document.getElementById('modalJobRequirements').textContent = req || '(Chưa có yêu cầu ứng viên)';\r\n");
      out.write("\r\n");
      out.write("    var expContainer = document.getElementById('modalExplanationContainer');\r\n");
      out.write("    if (exp && exp.length > 0) {\r\n");
      out.write("        document.getElementById('modalExplanation').textContent = exp;\r\n");
      out.write("        expContainer.style.display = 'block';\r\n");
      out.write("    } else {\r\n");
      out.write("        expContainer.style.display = 'none';\r\n");
      out.write("    }\r\n");
      out.write("\r\n");
      out.write("    var modal = new bootstrap.Modal(document.getElementById('detailModal'));\r\n");
      out.write("    modal.show();\r\n");
